108	import com.fream.back.domain.sale.entity.Sale;
109	import com.fream.back.domain.sale.entity.SaleStatus;
110	import com.fream.back.domain.sale.repository.SaleRepository;
111	import com.fream.back.domain.shipment.entity.SellerShipment;
