113	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
114	import com.fream.back.domain.shipment.exception.ShipmentException;
115	import com.fream.back.domain.shipment.repository.SellerShipmentRepository;
116	import com.fream.back.domain.warehouseStorage.service.command.WarehouseStorageCommandService;
117	import lombok.RequiredArgsConstructor;
118	import lombok.extern.slf4j.Slf4j;
119	import org.springframework.stereotype.Service;
120	import org.springframework.transaction.annotation.Transactional;
121	
122	/**
123	 * 판매자 배송 관련 비즈니스 로직을 처리하는 서비스
124	 */
125	@Slf4j
126	@Service
127	@RequiredArgsConstructor
128	public class SellerShipmentCommandService {
129	
130	    private final SellerShipmentRepository sellerShipmentRepository;
131	    private final SaleRepository saleRepository;
132	    private final WarehouseStorageCommandService warehouseStorageCommandService;
133	
134	    /**
135	     * 판매에 대한 판매자 배송 정보를 생성합니다.
136	     *
137	     * @param saleId 판매 ID
138	     * @param courier 택배사 이름
139	     * @param trackingNumber 운송장 번호
140	     * @return 생성된 판매자 배송 정보
141	     * @throws ShipmentException 판매 정보를 찾을 수 없는 경우 또는 배송 정보 생성 실패 시
142	     */
143	    @Transactional
144	    public SellerShipment createSellerShipment(Long saleId, String courier, String trackingNumber) {
145	        log.info("판매자 배송 정보 생성 시작: saleId={}, courier={}, trackingNumber={}",
146	                saleId, courier, trackingNumber);
147	
148	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
149	            log.warn("유효하지 않은 배송사 또는 운송장 번호: saleId={}", saleId);
150	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
151	        }
152	
153	        try {
154	            // Sale 조회
155	            Sale sale = saleRepository.findById(saleId)
156	                    .orElseThrow(() -> new ShipmentException(
157	                            ShipmentErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
158	                            "해당 Sale을 찾을 수 없습니다: " + saleId
159	                    ));
160	
161	            log.debug("판매 정보 조회: saleId={}, sellerId={}, currentStatus={}",
162	                    sale.getId(), sale.getSeller().getId(), sale.getStatus());
163	
164	            // SellerShipment 생성
165	            SellerShipment shipment = SellerShipment.builder()
166	                    .sale(sale)
167	                    .courier(courier)
168	                    .trackingNumber(trackingNumber)
169	                    .status(ShipmentStatus.IN_TRANSIT) // 배송 중 상태로 설정
170	                    .build();
171	
172	            // 연관관계 설정
173	            sale.assignSellerShipment(shipment);
174	
175	            SellerShipment savedShipment = sellerShipmentRepository.save(shipment);
176	            log.info("판매자 배송 정보 저장 완료: shipmentId={}, saleId={}",
177	                    savedShipment.getId(), saleId);
178	
179	            // 창고 보관 상품인 경우 추가 처리
180	            if (sale.isWarehouseStorage()) {
181	                log.info("창고 보관 상품 처리: saleId={}", saleId);
182	
183	                // 창고 보관 데이터 생성
184	                warehouseStorageCommandService.createSellerStorage(sale, sale.getSeller());
185	
186	                // 창고 보관 상태 업데이트
187	                sale.updateStatus(SaleStatus.IN_STORAGE);
188	                log.info("판매 상태 IN_STORAGE로 변경: saleId={}", saleId);
189	            }
190	
191	            return savedShipment;
192	
193	        } catch (ShipmentException e) {
194	            throw e;
195	        } catch (Exception e) {
196	            log.error("판매자 배송 정보 생성 실패: saleId={}, error={}", saleId, e.getMessage(), e);
197	            throw new ShipmentException(
198	                    ShipmentErrorCode.SALE_NOT_FOUND_FOR_SHIPMENT,
199	                    "판매자 배송 정보 생성 중 오류 발생: " + e.getMessage(),
200	                    e
201	            );
202	        }
203	    }
204	
205	    /**
206	     * 판매자 배송 정보를 업데이트합니다.
207	     *
208	     * @param shipmentId 배송 ID
209	     * @param courier 택배사 이름
210	     * @param trackingNumber 운송장 번호
211	     * @return 업데이트된 판매자 배송 정보
212	     * @throws ShipmentException 배송 정보를 찾을 수 없는 경우 또는 업데이트 실패 시
213	     */
214	    @Transactional
215	    public SellerShipment updateShipment(Long shipmentId, String courier, String trackingNumber) {
216	        log.info("판매자 배송 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
217	                shipmentId, courier, trackingNumber);
218	
219	        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
220	            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
221	            throw new ShipmentException(ShipmentErrorCode.TRACKING_INFO_REQUIRED);
222	        }
223	
224	        try {
225	            SellerShipment sellerShipment = sellerShipmentRepository.findById(shipmentId)
226	                    .orElseThrow(() -> new ShipmentException(
227	                            ShipmentErrorCode.SELLER_SHIPMENT_NOT_FOUND,
228	                            "해당 Shipment를 찾을 수 없습니다: " + shipmentId
229	                    ));
230	
231	            log.debug("판매자 배송 정보 조회: shipmentId={}, saleId={}, currentStatus={}",
232	                    sellerShipment.getId(),
233	                    sellerShipment.getSale().getId(),
234	                    sellerShipment.getStatus());
235	
236	            sellerShipment.updateTrackingInfo(courier, trackingNumber);
237	            log.info("판매자 배송 정보 업데이트 완료: shipmentId={}", shipmentId);
238	
239	            return sellerShipment;
240	
241	        } catch (ShipmentException e) {
242	            throw e;
243	        } catch (Exception e) {
244	            log.error("판매자 배송 정보 업데이트 실패: shipmentId={}, error={}",
245	                    shipmentId, e.getMessage(), e);
246	            throw new ShipmentException(
247	                    ShipmentErrorCode.SELLER_SHIPMENT_NOT_FOUND,
248	                    "판매자 배송 정보 업데이트 중 오류 발생: " + e.getMessage(),
249	                    e
250	            );
251	        }
252	    }
253	}

