446	    @Transactional
447	    public void updateShipmentStatuses() {
448	        log.info("전체 배송 상태 업데이트 시작");
449	
450	        // 1. IN_TRANSIT 또는 OUT_FOR_DELIVERY 상태의 OrderShipment 조회
451	        List<OrderShipment> shipments = orderShipmentRepository.findByStatusIn(
452	                List.of(ShipmentStatus.IN_TRANSIT, ShipmentStatus.OUT_FOR_DELIVERY)
453	        );
454	
455	        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());
456	
457	        int successCount = 0;
458	        int errorCount = 0;
459	
460	        for (OrderShipment shipment : shipments) {
461	            try {
462	                String trackingNumber = shipment.getTrackingNumber();
463	                if (trackingNumber == null || trackingNumber.isBlank()) {
464	                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
465	                    errorCount++;
466	                    continue;
467	                }
468	
469	                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
470	                        shipment.getId(), trackingNumber);
471	
472	                // 2. CJ대한통운에서 현재 배송 상태 추출
473	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
474	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
475	
476	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
477	                        shipment.getId(), currentStatus, newStatus);
478	
479	                // 현재 상태와 동일한 경우 중복 처리 방지
480	                if (shipment.getStatus() == newStatus) {
481	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
482	                            shipment.getId(), newStatus);
483	                    successCount++;
484	                    continue;
485	                }
486	
487	                // 3. 배송 상태가 DELIVERED인 경우 Order와 Shipment 상태 업데이트
488	                if (newStatus == ShipmentStatus.DELIVERED) {
489	                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());
490	
491	                    shipment.updateStatus(newStatus);
492	                    Order order = shipment.getOrder();
493	                    order.updateStatus(OrderStatus.COMPLETED);
494	
495	                    // 배송 완료 알림 전송
496	                    User buyer = order.getUser();
497	                    notificationCommandService.createNotification(
498	                            buyer.getId(),
499	                            NotificationCategory.SHOPPING,
500	                            NotificationType.BID,
501	                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
502	                    );
503	
504	                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
505	                            buyer.getId(), order.getId());
506	
507	                } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY &&
508	                        shipment.getStatus() != ShipmentStatus.OUT_FOR_DELIVERY) {
509	                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
510	                    shipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
511	
512	                } else {
513	                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
514	                            shipment.getId(), newStatus);
515	                    shipment.updateStatus(newStatus);
516	                }
517	
518	                orderShipmentRepository.save(shipment);
519	                successCount++;
520	
521	            } catch (Exception e) {
522	                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
523	                        shipment.getId(), e.getMessage(), e);
524	                errorCount++;
525	            }
526	        }
527	
528	        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
529	    }
