 33	
 34	    @Scheduled(cron = "0 0 */6 * * *")
 35	    public void scheduleShipmentStatusJob() {
 36	        try {
 37	            JobParameters jobParameters = new JobParametersBuilder()
 38	                    .addLong("timestamp", System.currentTimeMillis())
 39	                    .toJobParameters();
 40	            jobLauncher.run(updateShipmentStatusesJob, jobParameters);
 41	        } catch (Exception e) {
 42	            e.printStackTrace();
 43	        }
 44	    }
 45	}
