 47	package com.fream.back.domain.shipment.config;
 48	
 49	import com.fream.back.domain.notification.service.command.NotificationCommandService;
 50	import com.fream.back.domain.shipment.entity.OrderShipment;
 51	import com.fream.back.domain.shipment.entity.ShipmentStatus;
 52	import com.fream.back.domain.shipment.exception.ShipmentErrorCode;
 53	import com.fream.back.domain.shipment.exception.ShipmentException;
 54	import com.fream.back.domain.shipment.repository.OrderShipmentRepository;
 55	import com.fream.back.domain.shipment.service.command.OrderShipmentCommandService;
 56	import com.fream.back.global.utils.CjTrackingPlaywright;
 57	import com.fream.back.global.utils.PlaywrightBrowserManager;
 58	import jakarta.persistence.EntityManagerFactory;
 59	import lombok.RequiredArgsConstructor;
 60	import lombok.extern.slf4j.Slf4j;
 61	import org.jsoup.Jsoup;
 62	import org.jsoup.nodes.Document;
 63	import org.jsoup.select.Elements;
 64	import org.springframework.batch.core.Job;
 65	import org.springframework.batch.core.SkipListener;
 66	import org.springframework.batch.core.Step;
 67	import org.springframework.batch.core.configuration.annotation.StepScope;
 68	import org.springframework.batch.core.job.builder.JobBuilder;
 69	import org.springframework.batch.core.repository.JobRepository;
 70	import org.springframework.batch.core.step.builder.StepBuilder;
 71	import org.springframework.batch.item.ItemProcessor;
 72	import org.springframework.batch.item.database.JpaItemWriter;
 73	import org.springframework.batch.item.database.JpaPagingItemReader;
 74	import org.springframework.batch.item.database.builder.JpaPagingItemReaderBuilder;
 75	import org.springframework.context.annotation.Bean;
 76	import org.springframework.context.annotation.Configuration;
 77	import org.springframework.transaction.PlatformTransactionManager;
 78	
 79	
 80	/**
 81	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
 82	 */
 83	@Slf4j
 84	@Configuration
 85	@RequiredArgsConstructor
 86	public class UpdateShipmentStatusesJobConfig {
 87	
 88	    private final JobRepository jobRepository;
 89	    private final PlatformTransactionManager transactionManager;
 90	    private final EntityManagerFactory entityManagerFactory;
 91	
 92	    private final OrderShipmentRepository orderShipmentRepository;
 93	    private final NotificationCommandService notificationService;
 94	    private final OrderShipmentCommandService orderService;
 95	    private final CjTrackingPlaywright cjTrackingPlaywright;
 96	
 97	    private static final int CHUNK_SIZE = 50;
 98	    private static final int SKIP_LIMIT = 50;
 99	
100	    @Bean
101	    public Job updateShipmentStatusesJob() {
102	        log.info("배송 상태 업데이트 작업 구성");
103	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
104	                .start(updateShipmentStatusesStep())
105	                .build();
106	    }
107	
108	    @Bean
109	    public Step updateShipmentStatusesStep() {
110	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
111	
112	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
113	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
114	                .reader(shipmentItemReader())
115	                .processor(new ShipmentItemProcessor(
116	                        playwrightBrowserManager(), // Bean or new
117	                        notificationService,
118	                        orderService
119	                ))
120	                .writer(shipmentJpaItemWriter())
121	                .faultTolerant()
122	                .skip(Exception.class)
123	                .skipLimit(SKIP_LIMIT)
124	                .listener(shipmentSkipListener())
125	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
126	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
127	                .build();
128	    }
129	
130	    /**
131	     * 1) Reader: 상태가 IN_TRANSIT 또는 OUT_FOR_DELIVERY 인 OrderShipment 목록을 페이지 단위로 읽음
132	     */
133	    @Bean
134	    @StepScope
135	    public JpaPagingItemReader<OrderShipment> shipmentItemReader() {
136	        log.debug("배송 상태 업데이트 ItemReader 구성");
137	        return new JpaPagingItemReaderBuilder<OrderShipment>()
138	                .name("shipmentItemReader")
139	                .entityManagerFactory(entityManagerFactory)
140	                .pageSize(CHUNK_SIZE)
141	                .queryString("SELECT s FROM OrderShipment s WHERE s.status IN ('IN_TRANSIT','OUT_FOR_DELIVERY') AND s.trackingNumber IS NOT NULL")
142	                .build();
143	    }
144	
145	    /**
146	     * 2) Processor: 각 OrderShipment에 대해 CJ대한통운 페이지를 조회하여 상태 갱신
147	     *    - parseCjLogisticsStatus(...) 를 통해 배송 상태 파싱
148	     *    - DELIVERY 완료 시 알림, Order 상태 완료 등도 여기서 처리 가능
149	     */
150	    @Bean
151	    @StepScope
152	    public ItemProcessor<OrderShipment, OrderShipment> shipmentItemProcessor() {
153	        log.debug("배송 상태 업데이트 ItemProcessor 구성");
154	
155	        // 만약 Processor를 여러 단계로 나누고 싶다면 CompositeItemProcessorBuilder 사용도 가능
156	        return orderShipment -> {
157	            String trackingNumber = orderShipment.getTrackingNumber();
158	            Long shipmentId = orderShipment.getId();
159	
160	            if (trackingNumber == null || trackingNumber.isBlank()) {
161	                log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
162	                throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
163	            }
164	
165	            log.info("배송 상태 조회 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
166	                    shipmentId, trackingNumber, orderShipment.getStatus());
167	
168	            try {
169	                // 2-1) 현재 상태 가져오기
170	                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
171	                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}", shipmentId, currentStatus);
172	
173	                // 2-2) 매핑
174	                ShipmentStatus newStatus = mapToShipmentStatus(currentStatus);
175	                log.debug("배송 상태 매핑 결과: currentStatus={}, mappedStatus={}", currentStatus, newStatus);
176	
177	                // 현재 상태와 동일한 경우 중복 처리 방지
178	                if (orderShipment.getStatus() == newStatus) {
179	                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
180	                            shipmentId, newStatus);
181	                    return orderShipment;
182	                }
183	
184	                // 2-3) 상태에 따른 처리
185	                if (newStatus == ShipmentStatus.DELIVERED) {
186	                    log.info("배송 완료 처리: shipmentId={}, orderId={}",
187	                            shipmentId, orderShipment.getOrder().getId());
188	
189	                    orderShipment.updateStatus(ShipmentStatus.DELIVERED);
190	                    // Order 상태도 COMPLETED 로 변경
191	                    orderService.completeOrder(orderShipment.getOrder().getId());
192	                    // 알림 발송
193	                    notificationService.notifyShipmentCompleted(orderShipment.getOrder());
194	                }
195	                else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
196	                    log.info("배송 출발 처리: shipmentId={}", shipmentId);
197	                    orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
198	                    // 필요시 알림, 로직 추가
199	                }
200	                else {
201	                    log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
202	                    orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
203	                }
204	
205	                log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}", shipmentId, orderShipment.getStatus());
206	                return orderShipment; // Writer로 넘김
207	
208	            } catch (Exception e) {
209	                log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
210	                        shipmentId, trackingNumber, e.getMessage(), e);
211	
212	                // ShipmentException 타입이 아닌 경우 래핑
213	                if (!(e instanceof ShipmentException)) {
214	                    throw new ShipmentException(
215	                            ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
216	                            "배송 상태 조회 중 오류 발생: " + e.getMessage(),
217	                            e
218	                    );
219	                }
220	                throw e;
221	            }
222	        };
223	    }
224	
225	    /**
226	     * CJ대한통운 배송 상태 조회를 위한 메서드
227	     *
228	     * @param trackingNumber 운송장 번호
229	     * @return 배송 상태 텍스트
230	     * @throws Exception 조회 실패 시 발생
231	     */
232	    private String parseCjLogisticsStatus(String trackingNumber) throws Exception {
233	        log.debug("운송장 조회 시작 (Jsoup): trackingNumber={}", trackingNumber);
234	
235	        try {
236	            // 예시: 로직 단순화
237	            String url = "https://trace.cjlogistics.com/next/tracking.html?wblNo=" + trackingNumber;
238	            Document doc = Jsoup.connect(url).get();
239	            // tbody#statusDetail 의 마지막 tr => 5번째 td
240	            Elements rows = doc.select("tbody#statusDetail tr");
241	            if (rows.isEmpty()) {
242	                log.warn("배송 정보가 없음: trackingNumber={}", trackingNumber);
243	                throw new ShipmentException(
244	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
245	                        "배송 정보가 없습니다. trackingNo=" + trackingNumber
246	                );
247	            }
248	
249	            String status = rows.last().select("td").get(4).text();
250	            log.debug("운송장 조회 완료: trackingNumber={}, status={}", trackingNumber, status);
251	            return status;
252	
253	        } catch (Exception e) {
254	            log.error("운송장 조회 실패: trackingNumber={}, error={}", trackingNumber, e.getMessage(), e);
255	
256	            if (e instanceof ShipmentException) {
257	                throw e;
258	            }
259	
260	            throw new ShipmentException(
261	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
262	                    "배송 정보 조회 중 오류 발생: " + e.getMessage(),
263	                    e
264	            );
265	        }
266	    }
267	
268	    /**
269	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
270	     *
271	     * @param statusText 배송사 상태 텍스트
272	     * @return 매핑된 ShipmentStatus
273	     */
274	    private ShipmentStatus mapToShipmentStatus(String statusText) {
275	        return switch (statusText) {
276	            case "배송완료" -> ShipmentStatus.DELIVERED;
277	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
278	            default -> ShipmentStatus.IN_TRANSIT;
279	        };
280	    }
281	
282	    /**
283	     * 3) Writer: DB에 반영 (상태 갱신)
284	     */
285	    @Bean
286	    @StepScope
287	    public JpaItemWriter<OrderShipment> shipmentJpaItemWriter() {
288	        log.debug("배송 상태 업데이트 ItemWriter 구성");
289	        JpaItemWriter<OrderShipment> writer = new JpaItemWriter<>();
290	        writer.setEntityManagerFactory(entityManagerFactory);
291	        return writer;
292	    }
293	
294	    /**
295	     * SkipListener: 예외 발생 시 로그
296	     */
297	    @Bean
298	    public SkipListener<OrderShipment, OrderShipment> shipmentSkipListener() {
299	        return new SkipListener<>() {
300	            @Override
301	            public void onSkipInProcess(OrderShipment item, Throwable t) {
302	                if (item != null) {
303	                    log.error("[Skip] 배송 상태 처리 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
304	                            item.getId(),
305	                            item.getTrackingNumber(),
306	                            item.getStatus(),
307	                            t.getMessage(),
308	                            t);
309	                } else {
310	                    log.error("[Skip] 배송 상태 처리 스킵: item=null, 사유={}", t.getMessage(), t);
311	                }
312	            }
313	
314	            @Override
315	            public void onSkipInRead(Throwable t) {
316	                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
317	            }
318	
319	            @Override
320	            public void onSkipInWrite(OrderShipment item, Throwable t) {
321	                if (item != null) {
322	                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
323	                            item.getId(),
324	                            item.getTrackingNumber(),
325	                            item.getStatus(),
326	                            t.getMessage(),
327	                            t);
328	                } else {
329	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
330	                }
331	            }
332	        };
333	    }
334	
335	    /**
336	     * PlaywrightBrowserManager 빈 정의
337	     */
338	    @Bean
339	    public PlaywrightBrowserManager playwrightBrowserManager() {
340	        log.debug("Playwright 브라우저 매니저 빈 생성");
341	        return new PlaywrightBrowserManager();
342	    }
343	}

